  const simPick = kind => { const L = hubL(live()).length ? hubL(live()) : live(), sel = L.find(l => l.truck === TH.sel); return (kind === 'freeze' || kind === 'heat' || kind === 'door') ? (sel && coldOf(sel) ? sel : L.find(coldOf) || L[0]) : (sel || L[0]); };
